      Object.assign(result,{human:true,actor,note:note.trim()||'Sin comentario adicional',originalDecision:D.clone(old),reason:result.checks.some(c=>c.exempted)?'Finanzas autorizó las excepciones registradas y confirmó los demás criterios.':'Finanzas confirmó los datos. Todos los criterios aplicables se cumplen.'});state.results[id]=result;recordPayment(i,result);state.humanDecisions[id]=D.clone(result);event('human',id+' · Pagado',result.reason,result,id);
